  """
  package com.example.analyzer

  import android.util.Log
  import android.content.Context
  import android.app.*
  import java.util.*

  class CustomAnalyze : AndroidExecutor {
    override fun execute(context: Context, job: Job) {
      Log.d("CustomAnalyze", "Starting analysis")

      val openPorts = scanData.filter { it.ports.contains(it).not() }.map { it.id }
      val timestamp = job.time

      withApp {
        try {
          val result = application.applicationInfo.loadableApplications[0]

          if (result != null && result.url == scanData[0].url) {
            Log.d("CustomAnalyze", "Found open ports: ${openPorts.joinToString(", ")}")
            // Do something with the found open ports
          }
        } catch(e: Exception){
          Log.e("CustomAnalyze", "Error fetching application information")
        }
      }
    }
  }
  """.trimIndent()
}

// Define a sample ScanData

data class ScanData(val url: String, val ports: Set<String>) {
  operator fun invoke() = this
}
